1	import { Buffer, isUtf8 } from 'node:buffer';
2	import { mkdir, readdir, readFile, writeFile } from 'node:fs/promises';
3	import { createRequire } from 'node:module';
4	import {
5		charIn,
6		createRegExp,
7		exactly,
8		global,
9		maybe,
10		oneOrMore,
11		whitespace,
12		wordChar,
13	} from 'magic-regexp';
14	import * as path from 'pathe';
15	import { analyze } from 'yuku-analyzer';
16	
17	/**
18	 * Reusable create-react-app compatibility capabilities for a Vite build.
19	 *
20	 * Every export here is application agnostic: the shapes handled are the ones
21	 * create-react-app itself defines (HTML template placeholders, `process.env`
22	 * inlining, the ambient `global` identifier, webpack's automatic Node core
23	 * module polyfills, webpack's sloppy-mode CommonJS module wrapper, webpack
24	 * tilde specifiers, and the copied public directory). No capability branches on
25	 * an application name, revision, or source string.
26	 */
27	
28	export type CraEnvironment = Readonly<Record<string, string>>;
29	
30	const templatePlaceholder = createRegExp(
31		exactly('%').and(oneOrMore(wordChar).groupedAs('key')).and('%'),
32		[global],
33	);
34	
35	const tildePrefixedCssImport = createRegExp(
36		exactly('@import')
37			.and(oneOrMore(whitespace))
38			.and(maybe(exactly('url').and(maybe(whitespace)).and('(').and(maybe(whitespace))))
39			.and(charIn(`'"`))
40			.and('~'),
41		[global],
42	);
43	
44	const closingBodyTag = createRegExp(
45		exactly('<').and(maybe(whitespace)).and('/').and(maybe(whitespace)).and('body'),
46	);
47	
48	export function compareUtf16CodeUnits(left: string, right: string): number {
49		if (left === right) return 0;
50		return left < right ? -1 : 1;
51	}
52	
53	/**
54	 * Replace `%KEY%` template placeholders the way create-react-app's
55	 * InterpolateHtmlPlugin does: only keys present in the environment are
56	 * substituted, and unknown placeholders are preserved verbatim.
57	 */
58	export function substituteCraTemplatePlaceholders(
59		template: string,
60		environment: CraEnvironment,
61	): string {
62		return template.replace(templatePlaceholder, (match: string, key: string) =>
63			Object.hasOwn(environment, key) ? (environment[key] as string) : match,
64		);
65	}
66	
67	export type CraEntryDocumentOptions = Readonly<{
68		template: string;
69		entryModule: string;
70		environment?: CraEnvironment;
71		bootstrapModules?: readonly string[];
72	}>;
73	
74	/**
75	 * Turn a create-react-app `public/index.html` template into a Vite entry
76	 * document: placeholders are substituted and the application entry is injected
77	 * as a module script immediately before the closing body tag.
78	 *
79	 * `bootstrapModules` are imported by inline module scripts placed ahead of the
80	 * application entry. Module scripts evaluate in document order, so a bootstrap
81	 * listed here runs before the first application module — the position webpack
82	 * used for the bindings it injected into every module. Omitting the option
83	 * leaves the document byte-identical to one produced without it.
84	 */
85	export function craEntryDocument(options: CraEntryDocumentOptions): string {
86		const substituted = substituteCraTemplatePlaceholders(
87			options.template,
88			options.environment ?? {},
89		);
90		const bootstrap = (options.bootstrapModules ?? [])
91			.map((module) => `<script type="module">import ${JSON.stringify(module)};</script>\n  `)
92			.join('');
93		const script = `${bootstrap}<script type="module" src="${options.entryModule}"></script>`;
94		const match = closingBodyTag.exec(substituted);
95		if (!match) return `${substituted}${substituted.endsWith('\n') ? '' : '\n'}${script}\n`;
96		return `${substituted.slice(0, match.index)}  ${script}\n  ${substituted.slice(match.index)}`;
97	}
98	
99	/**
100	 * Build the `define` map create-react-app's DefinePlugin provides: one entry per
101	 * environment key plus the whole `process.env` object for dynamic access.
102	 */
103	export function craProcessEnvironmentDefines(
104		environment: CraEnvironment,
105	): Readonly<Record<string, string>> {
106		const keys = Object.keys(environment).sort(compareUtf16CodeUnits);
107		const sorted = Object.fromEntries(keys.map((key) => [key, environment[key] as string]));
108		return Object.freeze({
109			...Object.fromEntries(
110				keys.map((key) => [`process.env.${key}`, JSON.stringify(environment[key])]),
111			),
112			'process.env': JSON.stringify(sorted),
113		});
114	}
115	
116	/**
117	 * The ambient identifier webpack 4 provides to every module it bundles for the
118	 * browser. webpack's runtime declares `global` itself (its `node.global`
119	 * option defaults to `true` on the webpack 4 line create-react-app 3 and 4
120	 * pin), so a dependency written against Node's `global` keeps working inside a
121	 * webpack browser bundle. Vite emits no such declaration: the same dependency
122	 * reaches the browser with a free `global` reference and throws
123	 * `ReferenceError: global is not defined` on first evaluation. Mapping the
124	 * identifier onto `globalThis` restores exactly the binding webpack supplied
125	 * and nothing else — it is a compile-time substitution of one free identifier,
126	 * so member accesses, property keys and locally bound `global` names are left
127	 * alone, and modules that never mention it emit byte-identical output.
128	 */
129	export function craGlobalIdentifierDefines(): Readonly<Record<string, string>> {
130		return Object.freeze({ global: 'globalThis' });
131	}
132	
133	export type CraDefineConfig = Readonly<{ define: Readonly<Record<string, string>> }>;
134	export type CraDefinePlugin = Readonly<{ name: string; config(): CraDefineConfig }>;
135	
136	/**
137	 * Contribute the webpack `global` binding as a Vite `define` entry. It is
138	 * contributed through the plugin's own configuration rather than asked of every
139	 * consumer, so any build that adopts the create-react-app adapter inherits the
140	 * ambient identifier its bundler used to provide.
141	 */
142	export function createCraGlobalIdentifierPlugin(): CraDefinePlugin {
143		return {
144			name: 'versionless-cra-global-identifier',
145			config() {
146				return { define: craGlobalIdentifierDefines() };
147			},
148		};
149	}
150	
151	/**
152	 * webpack 4's automatic Node core module resolution table, reproduced verbatim
153	 * from the `node-libs-browser` package webpack 4 depends on.
154	 *
155	 * webpack 4 resolved a bare `require('stream')` in browser builds to a browser
156	 * shim package rather than to a Node builtin, so dependencies written against
157	 * Node's standard library kept working unchanged inside a create-react-app
158	 * bundle. Vite performs no such substitution: it treats every Node builtin as
159	 * an external and emits a `__vite-browser-external` stub, so the same
160	 * `require('stream')` yields `undefined` and the first dependency that reads a
161	 * property off it fails at load — `readable-stream` 1.x, for instance, throws
162	 * `TypeError: Object prototype may only be an Object or null: undefined` from
163	 * `inherits`.
164	 *
165	 * The entries `node-libs-browser` maps to `null` (`fs`, `net`, `child_process`,
166	 * `dns`, `dgram`, `tls`, `cluster`, `module`, `readline`, `repl`) are absent
167	 * here on purpose: webpack emitted an empty module for those and Vite's own
168	 * browser-external stub already occupies that role, so nothing is claimed about
169	 * them.
170	 */
171	export const craWebpackNodeCoreShimSpecifiers: Readonly<Record<string, string>> = Object.freeze({
172		_stream_duplex: 'readable-stream/duplex.js',
173		_stream_passthrough: 'readable-stream/passthrough.js',
174		_stream_readable: 'readable-stream/readable.js',
175		_stream_transform: 'readable-stream/transform.js',
176		_stream_writable: 'readable-stream/writable.js',
177		assert: 'assert/',
178		buffer: 'buffer/',
179		console: 'console-browserify',
180		constants: 'constants-browserify',
181		crypto: 'crypto-browserify',
182		domain: 'domain-browser',
183		events: 'events/',
184		http: 'stream-http',
185		https: 'https-browserify',
186		os: 'os-browserify/browser.js',
187		path: 'path-browserify',
188		process: 'process/browser.js',
189		punycode: 'punycode/',
190		querystring: 'querystring-es3/',
191		stream: 'stream-browserify',
192		string_decoder: 'string_decoder/',
193		sys: 'util/util.js',
194		timers: 'timers-browserify',
195		tty: 'tty-browserify',
196		url: 'url/',
197		util: 'util/util.js',
198		vm: 'vm-browserify',
199		zlib: 'browserify-zlib',
200	});
201	
202	const nodeProtocolPrefix = 'node:';
203	
204	/**
205	 * The core module name a bare import specifier asks for, or `null` when the
206	 * specifier is not one webpack 4 polyfilled. Both `stream` and `node:stream`
207	 * name the same module.
208	 */
209	export function craNodeCoreModuleName(source: string): string | null {
210		const bare = source.startsWith(nodeProtocolPrefix)
211			? source.slice(nodeProtocolPrefix.length)
212			: source;
213		return Object.hasOwn(craWebpackNodeCoreShimSpecifiers, bare) ? bare : null;
214	}
215	
216	/** The package a shim specifier belongs to, for a diagnosable failure. */
217	export function craNodeCoreShimPackage(specifier: string): string {
218		const segments = specifier.split('/').filter((segment) => segment.length > 0);
219		const first = segments[0] ?? specifier;
220		return first.startsWith('@') && segments.length > 1
221			? `${first}/${segments[1] as string}`
222			: first;
223	}
224	
225	/** Resolve a bare specifier to a file, the way a require from a directory would. */
226	export type CraModuleResolver = (specifier: string) => string;
227	
228	/**
229	 * A resolver that searches the application's own dependency closure, which is
230	 * what webpack 4 did: the shim packages arrive through react-scripts' transitive
231	 * closure and are resolved against the application being compiled, never against
232	 * the build tool's own installation.
233	 */
234	export function craApplicationModuleResolver(applicationRoot: string): CraModuleResolver {
235		const applicationRequire = createRequire(
236			path.join(path.resolve(applicationRoot), 'package.json'),
237		);
238		return (specifier) => applicationRequire.resolve(specifier);
239	}
240	
241	/**
242	 * Resolve one Node core module to its webpack 4 browser shim. A shim missing
243	 * from the application's closure is a hard failure naming the module, the
244	 * package webpack would have used, and where it was searched — never a silent
245	 * stub, because a silent stub is the defect this capability exists to remove.
246	 */
247	export function resolveCraNodeCoreModule(
248		module: string,
249		resolver: CraModuleResolver,
250		origin: string,
251	): string {
252		const specifier = craWebpackNodeCoreShimSpecifiers[module];
253		if (specifier === undefined)
254			throw new Error(`Node core module "${module}" has no webpack 4 browser shim`);
255		try {
256			return resolver(specifier);
257		} catch {
258			throw new Error(
259				`create-react-app compatibility: this build imports the Node core module "${module}", ` +
260					`which webpack 4 resolved to the browser shim "${specifier}". The package ` +
261					`"${craNodeCoreShimPackage(specifier)}" is absent from the application dependency ` +
262					`closure at ${origin}, so "${module}" cannot be provided and would reach the browser ` +
263					`as an undefined stub. Install it into that closure or drop the import.`,
264			);
265		}
266	}
267	
268	/**
269	 * The identifiers webpack 4 injected into every module it bundled for the
270	 * browser, and the core module each one is sourced from. `node.process`,
271	 * `node.Buffer` and `node.setImmediate` all default to `true` on the webpack 4
272	 * line create-react-app pins, so a dependency that reads `process.nextTick`,
273	 * constructs a `Buffer`, or calls `setImmediate` keeps working with no import.
274	 * Vite injects nothing, so those same references reach the browser free and the
275	 * first one evaluated throws `ReferenceError: process is not defined`.
276	 *
277	 * The bootstrap module below installs exactly these bindings, sourced from the
278	 * same shim packages the resolution table names, and it is evaluated before the
279	 * application entry. `global` is not listed: it is already supplied as a
280	 * compile-time substitution by the global identifier capability.
281	 */
282	export const craWebpackNodeInjectedGlobals: Readonly<Record<string, string>> = Object.freeze({
283		Buffer: 'buffer',
284		clearImmediate: 'timers',
285		process: 'process',
286		setImmediate: 'timers',
287	});
288	
289	/** The module id an entry document imports to install webpack's injected globals. */
290	export const craNodeGlobalsModuleId = 'virtual:versionless-cra-node-globals';
291	
292	const resolvedNodeGlobalsModuleId = `\0${craNodeGlobalsModuleId}`;
293	
294	/**
295	 * Source for the injected-globals bootstrap, built from files already resolved
296	 * out of the application's own closure. Assignment is conditional so a host that
297	 * genuinely provides one of these names keeps it.
298	 */
299	export function craNodeGlobalsBootstrapSource(
300		files: Readonly<{ process: string; buffer: string; timers: string }>,
301	): string {
302		return [
303			`import craProcess from ${JSON.stringify(files.process)};`,
304			`import craBuffer from ${JSON.stringify(files.buffer)};`,
305			`import craTimers from ${JSON.stringify(files.timers)};`,
306			'globalThis.process ??= craProcess;',
307			'globalThis.Buffer ??= craBuffer.Buffer;',
308			'globalThis.setImmediate ??= craTimers.setImmediate;',
309			'globalThis.clearImmediate ??= craTimers.clearImmediate;',
310			'',
311		].join('\n');
312	}
313	
314	export type CraResolvedRootConfig = Readonly<{ root: string }>;
315	export type CraNodeCoreModulePlugin = Readonly<{
316		name: string;
317		enforce: 'pre';
318		configResolved(config: CraResolvedRootConfig): void;
319		resolveId(source: string): string | null;
320		load(id: string): string | null;
321	}>;
322	
323	export type CraNodeCoreModuleOptions = Readonly<{ applicationRoot?: string }>;
324	
325	/**
326	 * Provide webpack 4's Node core module polyfills to a Vite build. Resolution is
327	 * lazy — a core module is only resolved when the module graph actually asks for
328	 * it — so an application that imports nothing from the standard library pays
329	 * nothing and cannot be failed by a shim it never needed.
330	 */
331	export function createCraNodeCoreModulePlugin(
332		options: CraNodeCoreModuleOptions = {},
333	): CraNodeCoreModulePlugin {
334		let applicationRoot = options.applicationRoot ?? '';
335		let resolver: CraModuleResolver | null = null;
336		const resolve = (module: string): string => {
337			if (!applicationRoot)
338				throw new Error('CRA node core module resolution has no application root');
339			resolver ??= craApplicationModuleResolver(applicationRoot);
340			return resolveCraNodeCoreModule(module, resolver, applicationRoot);
341		};
342		return {
343			name: 'versionless-cra-node-core-modules',
344			enforce: 'pre',
345			configResolved(config) {
346				if (!options.applicationRoot) applicationRoot = config.root;
347				resolver = null;
348			},
349			resolveId(source) {
350				if (source === craNodeGlobalsModuleId) return resolvedNodeGlobalsModuleId;
351				const module = craNodeCoreModuleName(source);
352				return module === null ? null : resolve(module);
353			},
354			load(id) {
355				if (id !== resolvedNodeGlobalsModuleId) return null;
356				return craNodeGlobalsBootstrapSource({
357					buffer: resolve('buffer'),
358					process: resolve('process'),
359					timers: resolve('timers'),
360				});
361			},
362		};
363	}
364	
365	/**
366	 * Rewrite webpack's tilde-prefixed bare specifiers in CSS `@import` rules to
367	 * plain bare specifiers, which Vite resolves through node resolution.
368	 */
369	export function rewriteWebpackTildeCssImports(code: string): string {
370		return code.replace(tildePrefixedCssImport, (match: string) => match.slice(0, -1));
371	}
372	
373	function pathWithoutQuery(id: string): string {
374		const index = id.indexOf('?');
375		return index === -1 ? id : id.slice(0, index);
376	}
377	
378	export type CraTransformResult = Readonly<{ code: string; map: null }>;
379	export type CraTransformPlugin = Readonly<{
380		name: string;
381		enforce: 'pre';
382		transform(code: string, id: string): CraTransformResult | null;
383	}>;
384	
385	export function createCraTildeCssImportPlugin(): CraTransformPlugin {
386		return {
387			name: 'versionless-cra-tilde-css-import',
388			enforce: 'pre',
389			transform(code, id) {
390				if (path.extname(pathWithoutQuery(id)) !== '.css') return null;
391				const rewritten = rewriteWebpackTildeCssImports(code);
392				return rewritten === code ? null : { code: rewritten, map: null };
393			},
394		};
395	}
396	
397	/**
398	 * webpack 4 evaluated every non-harmony module inside a plain function wrapper
399	 * — `function (module, exports, __webpack_require__) { … }` — in the enclosing
400	 * bundle's mode. The bundles create-react-app 3 and 4 emit carry no `"use
401	 * strict"` prologue for those wrappers, so a CommonJS dependency ran in
402	 * sloppy mode: an assignment to an undeclared name silently created a property
403	 * on the global object, and every later reference to that name — in the same
404	 * module or in any other — read it back off the global object.
405	 *
406	 * Vite emits ECMAScript modules, and module code is always strict. The same
407	 * assignment is now a write to an unresolvable reference, which throws
408	 * `ReferenceError: <name> is not defined` the moment the module is evaluated,
409	 * long before the application can mount.
410	 *
411	 * The capability below restores webpack's tolerance without unpicking strict
412	 * mode anywhere. A dependency module that webpack would have wrapped in sloppy
413	 * mode is scanned for exactly the names it assigns without declaring; for each
414	 * one a prelude creates the property on `globalThis` if nothing already holds
415	 * it. Strict mode only rejects assignments to references it cannot resolve, and
416	 * a property of the global object is resolvable, so the original assignment
417	 * evaluates unchanged — and, because the binding lives on the global object
418	 * rather than in the module, cross-module reads of the same name find the same
419	 * value webpack's implicit global gave them.
420	 *
421	 * Three properties matter, and each is enforced rather than asserted:
422	 *
423	 * - Application source is untouched. Only modules under a dependency directory
424	 *   are scanned, so first-party code keeps every strict-mode diagnostic.
425	 * - Harmony modules are untouched. webpack made those strict too, so a module
426	 *   carrying `import`/`export` is left exactly as it is.
427	 * - A module that cannot be analysed is a hard failure naming the module and
428	 *   the diagnostic, never a silent skip.
429	 */
430	
431	const dependencyDirectorySegment = 'node_modules';
432	
433	/**
434	 * The extensions webpack 4 fed through its sloppy CommonJS wrapper. `.mjs` is
435	 * absent on purpose: webpack forced those to harmony, hence to strict mode.
436	 */
437	const sloppyCommonJsExtensions: ReadonlySet<string> = new Set(['.js', '.cjs', '']);
438	
439	/** True when a module id lies inside a dependency directory. */
440	export function craIsDependencyModule(id: string): boolean {
441		return path.normalize(id).split('/').includes(dependencyDirectorySegment);
442	}
443	
444	export type CraSloppyModuleKind = 'sloppy-commonjs' | 'ecmascript-module' | 'unanalyzable';
445	
446	export type CraImplicitGlobalScan = Readonly<{
447		kind: CraSloppyModuleKind;
448		names: readonly string[];
449		diagnostics: readonly string[];
450	}>;
451	
452	/**
453	 * Classify a module the way webpack 4 did and, when it is one of the sloppy
454	 * CommonJS modules, report the names it assigns without ever declaring them.
455	 *
456	 * The scan rides a real scope resolution: a name counts only when a write
457	 * reference resolves to no binding in any enclosing scope, so a local variable,
458	 * a parameter, a `catch` binding or a hoisted `var` of the same name elsewhere
459	 * in the module never produces a false report, and a shadowed inner name never
460	 * hides a genuine implicit global.
461	 */
462	export function scanCraImplicitGlobals(code: string, id = 'dependency.js'): CraImplicitGlobalScan {
463		const script = analyze(code, { path: id, lang: 'js', sourceType: 'script' });
464		const scriptErrors = script.diagnostics.filter((entry) => entry.severity === 'error');
465		if (scriptErrors.length > 0) {
466			// Harmony syntax is the ordinary reason a script parse fails, and webpack
467			// ran those modules in strict mode as well. Anything that parses as
468			// neither is a module this capability cannot reason about.
469			const esm = analyze(code, { path: id, lang: 'js', sourceType: 'module' });
470			const esmErrors = esm.diagnostics.filter((entry) => entry.severity === 'error');
471			return esmErrors.length === 0
472				? Object.freeze({ kind: 'ecmascript-module', names: [], diagnostics: [] })
473				: Object.freeze({
474						kind: 'unanalyzable',
475						names: [],
476						diagnostics: esmErrors.map((entry) => entry.message),
477					});
478		}
479		if (script.imports.length > 0 || script.exports.length > 0)
480			return Object.freeze({ kind: 'ecmascript-module', names: [], diagnostics: [] });
481		const names = new Set<string>();
482		for (const reference of script.unresolvedReferences)
483			if (reference.isWrite) names.add(reference.name);
484		return Object.freeze({
485			kind: 'sloppy-commonjs',
486			names: [...names].sort(compareUtf16CodeUnits),
487			diagnostics: [],
488		});
489	}
490	
491	/**
492	 * The prelude that gives a sloppy-mode implicit global its binding. Creating
493	 * the property is conditional, so a name the host genuinely owns — or one an
494	 * earlier dependency already assigned — keeps the value it has; only the
495	 * binding webpack's global object would have carried is added.
496	 */
497	export function craImplicitGlobalPrelude(names: readonly string[]): string {
498		if (names.length === 0) return '';
499		const statements = names
500			.map((name) => {
501				const key = JSON.stringify(name);
502				return `if (!(${key} in globalThis)) globalThis[${key}] = void 0;`;
503			})
504			.join(' ');
505		return `/* webpack sloppy-mode implicit globals */ ${statements}`;
506	}
507	
508	/**
509	 * The module source with its implicit-global prelude installed. The prelude
510	 * occupies no line of its own — it is appended to the first line — so every
511	 * line number in the original module, and therefore every source map that
512	 * refers to it, still points where it did. A hashbang keeps the first line.
513	 */
514	export function craSloppyCommonJsSource(code: string, names: readonly string[]): string {
515		const prelude = craImplicitGlobalPrelude(names);
516		if (prelude === '') return code;
517		if (!code.startsWith('#!')) return `${prelude}${code}`;
518		const firstLineEnd = code.indexOf('\n');
519		if (firstLineEnd === -1) return `${code}\n${prelude}`;
520		return `${code.slice(0, firstLineEnd + 1)}${prelude}${code.slice(firstLineEnd + 1)}`;
521	}
522	
523	export type CraImplicitGlobalRecord = Readonly<{ id: string; names: readonly string[] }>;
524	
525	export type CraSloppyCommonJsGlobalsOptions = Readonly<{
526		observe?: (record: CraImplicitGlobalRecord) => void;
527	}>;
528	
529	/**
530	 * Reproduce webpack 4's sloppy-mode CommonJS wrapper for dependency modules.
531	 * A module that declares everything it assigns is returned untouched, so a
532	 * dependency closure with no implicit globals emits byte-identical output.
533	 */
534	export function createCraSloppyCommonJsGlobalsPlugin(
535		options: CraSloppyCommonJsGlobalsOptions = {},
536	): CraTransformPlugin {
537		return {
538			name: 'versionless-cra-sloppy-commonjs-globals',
539			enforce: 'pre',
540			transform(code, id) {
541				const file = pathWithoutQuery(id);
542				if (!craIsDependencyModule(file)) return null;
543				if (!sloppyCommonJsExtensions.has(path.extname(file))) return null;
544				const scan = scanCraImplicitGlobals(code, file);
545				if (scan.kind === 'unanalyzable')
546					throw new Error(
547						`create-react-app compatibility: the dependency module ${file} parses as neither ` +
548							`a script nor an ECMAScript module, so webpack 4's sloppy-mode CommonJS wrapper ` +
549							`cannot be reproduced for it and an implicit global it may rely on would reach ` +
550							`the browser as a ReferenceError. Parser diagnostics: ${scan.diagnostics.join('; ')}`,
551					);
552				if (scan.names.length === 0) return null;
553				options.observe?.({ id: file, names: scan.names });
554				return { code: craSloppyCommonJsSource(code, scan.names), map: null };
555			},
556		};
557	}
558	
559	/**
560	 * webpack 4 turned a module's bytes into text before any loader saw them, and it
561	 * did so leniently. `loader-runner`, the reader webpack 4 delegates every module
562	 * read to, calls `buffer.toString("utf-8")` and then strips a leading byte order
563	 * mark; Node's UTF-8 decoder never fails, so a byte sequence that is not
564	 * well-formed UTF-8 becomes U+FFFD REPLACEMENT CHARACTER and the module keeps
565	 * loading. Rolldown, the bundler Vite 8 builds with, requires a module source to
566	 * be valid UTF-8 and refuses to load one that is not — `stream did not contain
567	 * valid UTF-8` — so a dependency stored in a legacy single-byte encoding stops
568	 * the build outright where webpack carried it.
569	 *
570	 * The semantics reproduced here were measured, not assumed. A webpack 4.44.2
571	 * create-react-app production build was read back byte by byte for a dependency
572	 * that ships one file in ISO-8859-1 and a sibling file carrying the same names
573	 * in valid UTF-8:
574	 *
575	 * - The ISO-8859-1 file's names reached the bundle with U+FFFD in place of each
576	 *   invalid byte — `"Esa�"`, not `"Esaù"`.
577	 * - The sibling UTF-8 file's identical names reached the same bundle intact, as
578	 *   `"Esaù"`.
579	 *
580	 * The second observation is the control: it rules out the tempting hypothesis
581	 * that webpack decoded the bytes as ISO-8859-1. It did not. It decoded them as
582	 * UTF-8 and substituted, losing the accents, and the application it was building
583	 * shipped that way. Reproducing webpack means reproducing the loss, because
584	 * parity with the bundler being replaced is the property under test — not a
585	 * better answer than the one production already had.
586	 *
587	 * A note on freeze order: this capability postdates the tranche-one adapter
588	 * freeze (composite fingerprint d9f75ef6…). It was written after that freeze was
589	 * superseded and before the freeze boundary that governs any later re-run, so no
590	 * measurement recorded under d9f75ef6 was taken with it in place.
591	 */
592	
593	/**
594	 * The extensions this capability decodes. These are the JavaScript module
595	 * sources webpack 4 fed through `babel-loader`, all of which arrived as text
596	 * through the lenient reader above. Stylesheets, JSON, and binary assets are not
597	 * listed: they travel a different Vite pipeline whose loading this capability
598	 * does not intercept, and nothing is claimed about them.
599	 */
600	const decodableModuleExtensions: ReadonlySet<string> = new Set([
601		'.cjs',
602		'.js',
603		'.jsx',
604		'.mjs',
605		'.ts',
606		'.tsx',
607	]);
608	
609	const byteOrderMarkCodeUnit = 0xfeff;
610	
611	/**
612	 * What a module's leading bytes say about its encoding. Only `utf-8` and
613	 * `utf-8-with-invalid-bytes` are decodable here; the rest are named so a refusal
614	 * can say what it refused.
615	 */
616	export type CraModuleSourceEncoding =
617		| 'utf-8'
618		| 'utf-8-with-invalid-bytes'
619		| 'utf-16le'
620		| 'utf-16be'
621		| 'utf-32le'
622		| 'utf-32be';
623	
624	function startsWithBytes(bytes: Uint8Array, prefix: readonly number[]): boolean {
625		if (bytes.length < prefix.length) return false;
626		return prefix.every((byte, index) => bytes[index] === byte);
627	}
628	
629	/**
630	 * Classify a module source by its bytes alone. The byte order marks are checked
631	 * first because none of them is valid UTF-8, so a UTF-16 or UTF-32 file would
632	 * otherwise be indistinguishable from a legacy single-byte one. Everything else
633	 * is decided by a real UTF-8 validation of the whole buffer — never by a file
634	 * name, a path, or a package.
635	 */
636	export function craModuleSourceEncoding(bytes: Uint8Array): CraModuleSourceEncoding {
637		if (startsWithBytes(bytes, [0xff, 0xfe, 0x00, 0x00])) return 'utf-32le';
638		if (startsWithBytes(bytes, [0x00, 0x00, 0xfe, 0xff])) return 'utf-32be';
639		if (startsWithBytes(bytes, [0xff, 0xfe])) return 'utf-16le';
640		if (startsWithBytes(bytes, [0xfe, 0xff])) return 'utf-16be';
641		return isUtf8(bytes) ? 'utf-8' : 'utf-8-with-invalid-bytes';
642	}
643	
644	function utf8SequenceLength(lead: number): number {
645		if (lead <= 0x7f) return 1;
646		if (lead >= 0xc2 && lead <= 0xdf) return 2;
647		if (lead >= 0xe0 && lead <= 0xef) return 3;
648		if (lead >= 0xf0 && lead <= 0xf4) return 4;
649		return 0;
650	}
651	
652	/**
653	 * The offset of every byte that begins a sequence UTF-8 cannot represent —
654	 * exactly the positions Node's decoder substitutes a U+FFFD for. This is the
655	 * measured fact the capability is keyed on, and it is what a diagnostic reports.
656	 * Overlong forms, surrogate code points and out-of-range lead bytes are all
657	 * rejected, so the scan agrees with `isUtf8` on whether a buffer is well formed.
658	 */
659	export function craInvalidUtf8ByteOffsets(bytes: Uint8Array): readonly number[] {
660		const offsets: number[] = [];
661		let index = 0;
662		while (index < bytes.length) {
663			const lead = bytes[index] as number;
664			const length = utf8SequenceLength(lead);
665			if (length === 0) {
666				offsets.push(index);
667				index += 1;
668				continue;
669			}
670			if (length === 1) {
671				index += 1;
672				continue;
673			}
674			const lowestSecond = lead === 0xe0 ? 0xa0 : lead === 0xf0 ? 0x90 : 0x80;
675			const highestSecond = lead === 0xed ? 0x9f : lead === 0xf4 ? 0x8f : 0xbf;
676			let wellFormed = index + length <= bytes.length;
677			if (wellFormed) {
678				const second = bytes[index + 1] as number;
679				wellFormed = second >= lowestSecond && second <= highestSecond;
680				for (let step = 2; wellFormed && step < length; step += 1) {
681					const continuation = bytes[index + step] as number;
682					wellFormed = continuation >= 0x80 && continuation <= 0xbf;
683				}
684			}
685			if (!wellFormed) {
686				offsets.push(index);
687				index += 1;
688				continue;
689			}
690			index += length;
691		}
692		return Object.freeze(offsets);
693	}
694	
695	/**
696	 * webpack 4's `utf8BufferToString`, reproduced: decode the whole buffer as UTF-8
697	 * with substitution, then drop a leading byte order mark. `Buffer.prototype
698	 * .toString('utf8')` is the same call `loader-runner` makes, so this is the
699	 * decoder itself rather than a reimplementation of it.
700	 */
701	export function craWebpackDecodedSource(bytes: Uint8Array): string {
702		const text = Buffer.from(bytes.buffer, bytes.byteOffset, bytes.byteLength).toString('utf8');
703		return text.charCodeAt(0) === byteOrderMarkCodeUnit ? text.slice(1) : text;
704	}
705	
706	/**
707	 * The text webpack 4 would have handed its loaders for these bytes, or a hard
708	 * failure naming the encoding.
709	 *
710	 * The refusal is deliberately narrower than webpack. webpack decoded a UTF-16
711	 * file as UTF-8 too, and produced mojibake for it; that is not a capability
712	 * worth reproducing, and pretending to have decoded such a file would hide a
713	 * broken build behind a plausible-looking string. Naming the encoding and
714	 * stopping is the truthful outcome.
715	 */
716	export function craDecodedModuleSource(bytes: Uint8Array, origin: string): string {
717		const encoding = craModuleSourceEncoding(bytes);
718		if (encoding === 'utf-8' || encoding === 'utf-8-with-invalid-bytes')
719			return craWebpackDecodedSource(bytes);
720		throw new Error(
721			`create-react-app compatibility: the dependency module ${origin} is stored in ${encoding}, ` +
722				`which is not UTF-8 and is not an encoding this capability decodes. webpack 4 read every ` +
723				`module as UTF-8 regardless of its encoding, so it would have turned this file into ` +
724				`mojibake rather than reading it correctly, and reproducing that is not claimed here. ` +
725				`Re-encode the file as UTF-8 or drop the import.`,
726		);
727	}
728	
729	export type CraDecodedModuleRecord = Readonly<{
730		id: string;
731		encoding: CraModuleSourceEncoding;
732		invalidByteOffsets: readonly number[];
733	}>;
734	
735	export type CraNonUtf8ModuleSourceOptions = Readonly<{
736		observe?: (record: CraDecodedModuleRecord) => void;
737	}>;
738	
739	export type CraLoadPlugin = Readonly<{
740		name: string;
741		enforce: 'pre';
742		load(id: string): Promise<string | null>;
743	}>;
744	
745	/**
746	 * Supply webpack 4's lenient module-source decoding to a Vite build.
747	 *
748	 * The hook reads the bytes and validates them. A module whose bytes are valid
749	 * UTF-8 is returned to Vite untouched — the hook yields `null`, Vite loads the
750	 * file exactly as it always did, and the build is byte-for-byte what it would
751	 * have been without this capability. Only a module that Vite's bundler would
752	 * refuse outright is decoded here, and only then.
753	 *
754	 * The scope is the dependency closure, for the same reason the sloppy-mode
755	 * wrapper is scoped there: an application's own source with invalid bytes in it
756	 * is a defect in the application, and silently substituting characters into
757	 * first-party code would hide it. Dependencies are different — they are frozen
758	 * artifacts the migration cannot edit, and webpack already shipped them decoded
759	 * this way.
760	 *
761	 * The cost is one extra file read per dependency JavaScript module: the bytes
762	 * are read to be validated, and read again by Vite when they are valid. That is
763	 * paid deliberately, because handing Vite a string for every dependency would
764	 * substitute this capability's loading for Vite's own on files that never needed
765	 * it, and the untouched claim above would stop being true.
766	 */
767	export function createCraNonUtf8ModuleSourcePlugin(
768		options: CraNonUtf8ModuleSourceOptions = {},
769	): CraLoadPlugin {
770		return {
771			name: 'versionless-cra-non-utf8-module-source',
772			enforce: 'pre',
773			async load(id) {
774				if (id.startsWith('\0')) return null;
775				const file = pathWithoutQuery(id);
776				if (!craIsDependencyModule(file)) return null;
777				if (!decodableModuleExtensions.has(path.extname(file))) return null;
778				let bytes: Uint8Array;
779				try {
780					bytes = await readFile(file);
781				} catch {
782					return null;
783				}
784				const encoding = craModuleSourceEncoding(bytes);
785				if (encoding === 'utf-8') return null;
786				const source = craDecodedModuleSource(bytes, file);
787				options.observe?.({
788					id: file,
789					encoding,
790					invalidByteOffsets: craInvalidUtf8ByteOffsets(bytes),
791				});
792				return source;
793			},
794		};
795	}
796	
797	async function filesBelow(directory: string): Promise<string[]> {
798		const files: string[] = [];
799		for (const entry of await readdir(directory, { withFileTypes: true })) {
800			const item = path.join(directory, entry.name);
801			if (entry.isDirectory()) files.push(...(await filesBelow(item)));
802			else if (entry.isFile()) files.push(item);
803		}
804		return files;
805	}
806	
807	/**
808	 * The create-react-app public directory inventory: every file below the
809	 * directory except the excluded template, as sorted relative POSIX paths.
810	 */
811	export async function craPublicAssetPaths(
812		directory: string,
813		exclude: readonly string[] = [],
814	): Promise<readonly string[]> {
815		const excluded = new Set(exclude);
816		return (await filesBelow(directory))
817			.map((file) => path.relative(directory, file).split(path.sep).join('/'))
818			.filter((file) => !excluded.has(file))
819			.sort(compareUtf16CodeUnits);
820	}
821	
822	export type CraResolvedBuildConfig = Readonly<{ build: Readonly<{ outDir: string }> }>;
823	export type CraOutputPlugin = Readonly<{
824		name: string;
825		configResolved(config: CraResolvedBuildConfig): void;
826		closeBundle: Readonly<{ order: 'post'; sequential: true; handler(): Promise<void> }>;
827	}>;
828	
829	export type CraPublicDirectoryOptions = Readonly<{
830		directory: string;
831		exclude?: readonly string[];
832	}>;
833	
834	/**
835	 * Copy the create-react-app public directory into the build output the way
836	 * `react-scripts build` does, excluding the HTML template that becomes the
837	 * bundled entry document.
838	 */
839	export function createCraPublicDirectoryPlugin(
840		options: CraPublicDirectoryOptions,
841	): CraOutputPlugin {
842		let outputDirectory = '';
843		return {
844			name: 'versionless-cra-public-directory',
845			configResolved(config) {
846				outputDirectory = path.resolve(config.build.outDir);
847			},
848			closeBundle: {
849				order: 'post',
850				sequential: true,
851				async handler() {
852					if (!outputDirectory) throw new Error('CRA public directory outDir is unresolved');
853					for (const file of await craPublicAssetPaths(
854						options.directory,
855						options.exclude ?? [],
856					)) {
857						const destination = path.join(outputDirectory, file);
858						await mkdir(path.dirname(destination), { recursive: true });
859						await writeFile(
860							destination,
861							await readFile(path.join(options.directory, file)),
862						);
863					}
864				},
865			},
866		};
867	}
868	
869	export type CraViteAdapterOptions = Readonly<{
870		publicDirectory: string;
871		templateFile?: string;
872		applicationRoot?: string;
873		observeImplicitGlobals?: (record: CraImplicitGlobalRecord) => void;
874		observeDecodedModules?: (record: CraDecodedModuleRecord) => void;
875	}>;
876	
877	export type CraViteAdapterPlugins = readonly [
878		CraLoadPlugin,
879		CraTransformPlugin,
880		CraTransformPlugin,
881		CraNodeCoreModulePlugin,
882		CraDefinePlugin,
883		CraOutputPlugin,
884	];
885	
886	/**
887	 * The create-react-app compatibility plugin set: webpack's lenient module-source
888	 * decoding, tilde CSS specifier rewriting, webpack's sloppy-mode CommonJS
889	 * wrapper for dependency modules, webpack's automatic Node core module
890	 * polyfills, the ambient `global` identifier, plus public directory
891	 * replication.
892	 *
893	 * Decoding leads, because it is the only capability here that acts on bytes: a
894	 * module has to become text before any transform above can read it.
895	 */
896	export function createCraViteAdapter(options: CraViteAdapterOptions): CraViteAdapterPlugins {
897		return [
898			createCraNonUtf8ModuleSourcePlugin(
899				options.observeDecodedModules === undefined
900					? {}
901					: { observe: options.observeDecodedModules },
902			),
903			createCraTildeCssImportPlugin(),
904			createCraSloppyCommonJsGlobalsPlugin(
905				options.observeImplicitGlobals === undefined
906					? {}
907					: { observe: options.observeImplicitGlobals },
908			),
909			createCraNodeCoreModulePlugin(
910				options.applicationRoot === undefined
911					? {}
912					: { applicationRoot: options.applicationRoot },
913			),
914			createCraGlobalIdentifierPlugin(),
915			createCraPublicDirectoryPlugin({
916				directory: options.publicDirectory,
917				exclude: [options.templateFile ?? 'index.html'],
918			}),
919		];
920	}
